import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"Page 23 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"23","title":"Page 23 | Home","prev":"/page/22/","next":"/page/24/","posts":[{"title":"使用letsencrypt为自己的网站加密","url":"/posts/2018-04-08-website-https/","date":"2018-04-08 20:51","tags":["site","ssl"],"html":"<p>好吧，这次博客的更新稍微有点迟到了。因为自己各种忙着考驾照什么的，不过新的一年又要有新的开始了。最近买了 VPS 也就开始折腾起来了，讲讲如何用 letsencrypt 来给自己的网站颁发不要钱的证书，而且最近还支持通配符的二级域名了，想怎么开子网站都行！！！</p>\\n<h2 id=\\"dehydrated\\" tabindex=\\"-1\\">dehydrated <a class=\\"header-anchor\\" href=\\"#dehydrated\\" aria-label=\\"Permalink to &quot;dehydrated&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>浏览器的证书签名的步骤实在是很麻烦，所以有位热心的学生做了一个自动化脚本，可以自动生成脚本并且可以和其他脚本一起使用。达到一键签名证书。</p>\\n<h2 id=\\"letsencrypt-cloudflare-hook\\" tabindex=\\"-1\\">letsencrypt-cloudflare-hook <a class=\\"header-anchor\\" href=\\"#letsencrypt-cloudflare-hook\\" aria-label=\\"Permalink to &quot;letsencrypt-cloudflare-hook&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我把自己的 DNS 服务托管到 cloudflare 上，还可以使用 cloudflare 提供免费的 CDN 服务。最重要的一点是 cloudflare 有 API 接口。利用这个接口就可以自动完成 DNS-01 challenge。简单的来说，就是通过添加一条 DNS 记录来证明自己对这个域名的所有权，才能给这个域名颁发证书。</p>\\n<h2 id=\\"安装过程\\" tabindex=\\"-1\\">安装过程 <a class=\\"header-anchor\\" href=\\"#安装过程\\" aria-label=\\"Permalink to &quot;安装过程&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>知道了这两个工具之后，我们就可以开始配置证书了。具体的流程都写在项目的<a href=\\"https://github.com/kappataumu/letsencrypt-cloudflare-hook/blob/master/README.md\\" target=\\"_blank\\" rel=\\"noreferrer\\">文档</a>里面了。我这里主要是讲述下遇到的坑，首先我自己的服务器环境是 CentOS7，使用的是默认的 python2 的环境。需要安装<code>cryptography</code>的库才能顺利完成编译。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> yum</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> gcc</span><span style=\\"color:#032F62\\"> libffi-devel</span><span style=\\"color:#032F62\\"> python-devel</span><span style=\\"color:#032F62\\"> openssl-devel</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>其次，配置环境最好保存在<code>dehydrated/config</code>里，这样就没必要每次都设置环境变量。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_EMAIL=user@example.com\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_KEY=K9uX2HyUjeWg5AhAb\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">echo</span><span style=\\"color:#032F62\\"> \\"export CF_DEBUG=true\\"</span><span style=\\"color:#D73A49\\"> >></span><span style=\\"color:#032F62\\"> config</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>CF_KEY 就是 cloudflare 里面的 Global API Key，替换一下就好了。因为我们要配置的域名包含所有的二级域名，所以需要新建一个<code>dehydrated/domains.txt</code>文件，并写入：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>icehoney.me *.icehoney.me</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样就会对主域名和所有二级域名生效。</p>\\n<p>之后再执行命令，<code>./dehydrated -c -t dns-01 -k 'hooks/cloudflare/hook.py'</code>。如果没有问题就可以看到成功生成的日志。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://github.com/lukas2511/dehydrated\\" target=\\"_blank\\" rel=\\"noreferrer\\">dehydrated</a></p>\\n<p><a href=\\"https://github.com/kappataumu/letsencrypt-cloudflare-hook\\" target=\\"_blank\\" rel=\\"noreferrer\\">letsencrypt-cloudflare-hook</a></p>\\n<p><a href=\\"https://stackoverflow.com/questions/22073516/failed-to-install-python-cryptography-package-with-pip-and-setup-py\\" target=\\"_blank\\" rel=\\"noreferrer\\">Failed to install Python Cryptography package with PIP and setup.py\\nAsk Question</a></p>\\n"},{"title":"浏览器的渲染性能","url":"/posts/2018-02-13-rendering-performance/","date":"2018-02-13 20:44","tags":["browser"],"html":"<p>不知不觉，2018 年的春节也要来临了。今年只是元旦回家了，春节并不打算回家。回家曾经是一件美好的事情，不知从何时开始，却是那么的揪心。最近也有读很多关于性能优化和底层的前端知识。不想就此停滞，只能不断前进。</p>\\n<h2 id=\\"浏览器渲染\\" tabindex=\\"-1\\">浏览器渲染 <a class=\\"header-anchor\\" href=\\"#浏览器渲染\\" aria-label=\\"Permalink to &quot;浏览器渲染&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们都知道，现在主流显示器的频率是 60Hz，也就是 1 秒要刷新 60 次。这样才能保持画面的流畅，特别是玩游戏的时候，我们非常在意帧数。前端开发也是一样，所以我们每一项操作都最好在 10 毫秒之内完成，否则会产生所谓的卡顿现象，影响用户体验。</p>\\n<h2 id=\\"渲染过程\\" tabindex=\\"-1\\">渲染过程 <a class=\\"header-anchor\\" href=\\"#渲染过程\\" aria-label=\\"Permalink to &quot;渲染过程&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><img src=\\"/assets/frame-full.jpg\\" alt=\\"render pipeline\\" loading=\\"lazy\\"></p>\\n<p>浏览器的渲染主要是分为 5 个步骤，我们需要了解这些知识才能编写性能更好的代码。</p>\\n<ol>\\n<li>JavaScript 我们经常使用 JS 来实现一些复杂的视觉效果，数据排序，DOM 操作等等。</li>\\n<li>样式计算 此过程是根据样式匹配选择器来计算哪些元素应用哪些 CSS 规则的过程。不过浏览器会对常用的选择器进行性能优化，例如类选择器。</li>\\n<li>布局 在知道每个元素的应用规则之后，浏览器开始计算所需要的空间大小以及其处在屏幕的位置。网页的布局中，一个元素的变化会影响到其他元素的位置。例如 Body 的宽度变窄之后其子元素的宽度也都会发生变化。</li>\\n<li>绘制 绘制是填充像素的过程。它涉及绘出文本、颜色、图像、边框和阴影，基本上包括元素的每个可视部分。绘制一般是在多个表面（通常称为层）上完成的。</li>\\n<li>合成 由于页面的各部分可能被绘制到多层，由此它们需要按正确顺序绘制到屏幕上，以便正确渲染页面。对于与另一元素重叠的元素来说，这点特别重要，因为一个错误可能使一个元素错误地出现在另一个元素的上层。</li>\\n</ol>\\n<h2 id=\\"js-css-样式-布局-绘制-合成\\" tabindex=\\"-1\\">JS / CSS &gt; 样式 &gt; 布局 &gt; 绘制 &gt; 合成 <a class=\\"header-anchor\\" href=\\"#js-css-样式-布局-绘制-合成\\" aria-label=\\"Permalink to &quot;JS / CSS &gt; 样式 &gt; 布局 &gt; 绘制 &gt; 合成&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><img src=\\"/assets/frame-full.jpg\\" alt=\\"render pipeline\\" loading=\\"lazy\\"></p>\\n<p>如果修改了元素的布局属性，也就是改变了元素的几何属性（例如宽度，高度）。那么浏览器就必须检查所有元素，然后重新排版页面。任何受影响的部分都要重新绘制，再重新合成。</p>\\n<h2 id=\\"js-css-样式-绘制-合成\\" tabindex=\\"-1\\">JS / CSS &gt; 样式 &gt; 绘制 &gt; 合成 <a class=\\"header-anchor\\" href=\\"#js-css-样式-绘制-合成\\" aria-label=\\"Permalink to &quot;JS / CSS &gt; 样式 &gt; 绘制 &gt; 合成&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><img src=\\"/assets/frame-no-layout.jpg\\" alt=\\"render pipeline no layout\\" loading=\\"lazy\\"></p>\\n<p>如果只修改了元素的绘制属性，例如背景图片或者文字颜色，并不会对其他元素的布局造成影响。浏览器会跳过布局，但仍然执行绘制。</p>\\n<h2 id=\\"js-css-样式-合成\\" tabindex=\\"-1\\">JS / CSS &gt; 样式 &gt; 合成 <a class=\\"header-anchor\\" href=\\"#js-css-样式-合成\\" aria-label=\\"Permalink to &quot;JS / CSS &gt; 样式 &gt; 合成&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><img src=\\"/assets/frame-no-layout-paint.jpg\\" alt=\\"render pipeline no layout\\" loading=\\"lazy\\"></p>\\n<p>目前既不要绘制也不要布局的属性只有<code>transform</code>属性和<code>opacity</code>属性。所以在实现 CSS 动画的时候，优先使用这两个属性。</p>\\n<p>如何查询 CSS 属性触发上面 3 个流程的哪一个，可以去<a href=\\"https://csstriggers.com/\\" target=\\"_blank\\" rel=\\"noreferrer\\">CSS Triggers</a> 查询。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/rendering/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Rendering Performance</a></p>\\n"},{"title":"JavaScript中的数据类型","url":"/posts/2018-01-16-javascript-types/","date":"2018-01-16 22:44","tags":["js"],"html":"<p>隔了一个月，我又来发博客了。最近的工作老是在写 CSS 和 HTML。但是我更想学习 JS 啊！我一直都觉得 HTML 和 CSS 是属于设计范畴的，而 JS 才是真正属于工程师的逻辑范畴。\\n况且最近 Github 上有一个神奇的项目<a href=\\"https://github.com/emilwallner/Screenshot-to-code-in-Keras\\" target=\\"_blank\\" rel=\\"noreferrer\\">Screenshot-to-code-in-Keras</a>可以把截图直接生成 HTML 代码，我觉得只是单纯的从 PSD 翻译成页面的工作迟早要被淘汰。</p>\\n<p>最近在读 You Don't Know JS 这本书。书上讲解了很多关于 JS 的细节知识，对于深入了解 JS 有很大帮助。所以想在读的过程中把一些觉得有意思的东西记下来，便于以后复习。</p>\\n<h2 id=\\"类型\\" tabindex=\\"-1\\">类型 <a class=\\"header-anchor\\" href=\\"#类型\\" aria-label=\\"Permalink to &quot;类型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JavaScript 中有七种内置类型：</p>\\n<ol>\\n<li>空值(null)</li>\\n<li>未定义(undefined)</li>\\n<li>布尔值(boolean)</li>\\n<li>数字(number)</li>\\n<li>字符串(string)</li>\\n<li>对象(object)</li>\\n<li>符号(symbol, ES6 新增)</li>\\n</ol>\\n<p>除了对象之外，通称基本类型。</p>\\n<h2 id=\\"javascript-中的设计-bug\\" tabindex=\\"-1\\">JavaScript 中的设计 BUG <a class=\\"header-anchor\\" href=\\"#javascript-中的设计-bug\\" aria-label=\\"Permalink to &quot;JavaScript 中的设计 BUG&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">typeof</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#D73A49\\"> ===</span><span style=\\"color:#032F62\\"> 'object'</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#6A737D\\">// true</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>正确的返回结果应该是 null。但这个 BUG 由来已久，修复反而会出问题。所以我们需要使用复合条件来判断：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">a </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> a </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'object'</span><span style=\\"color:#24292E\\">;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来是<code>NaN</code>的问题：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> a </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 2</span><span style=\\"color:#D73A49\\"> /</span><span style=\\"color:#032F62\\"> 'foo'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> b </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'foo'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">// NaN</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// \\"foo\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#24292E\\">(a); </span><span style=\\"color:#6A737D\\">// true</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">window.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#24292E\\">(b); </span><span style=\\"color:#6A737D\\">// true</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">NaN</span><span style=\\"color:#D73A49\\"> ===</span><span style=\\"color:#005CC5\\"> NaN</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#6A737D\\">// false</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>很显然&quot;foo&quot;不是 NaN，但显然它也不是数字。这个 BUG 也存在很久了，在 ES6 时代，我们可以使用 <code>Number.isNaN</code> 来解决。\\nES6 之前的 polyfill 是：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">Number.isNaN) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  Number.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">n</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> n </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'number'</span><span style=\\"color:#D73A49\\"> &#x26;&#x26;</span><span style=\\"color:#24292E\\"> window.</span><span style=\\"color:#6F42C1\\">isNaN</span><span style=\\"color:#24292E\\">(n);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>并且 NaN 是 JS 中唯一一个不等于自身的值。</p>\\n<h2 id=\\"值和类型\\" tabindex=\\"-1\\">值和类型 <a class=\\"header-anchor\\" href=\\"#值和类型\\" aria-label=\\"Permalink to &quot;值和类型&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JavaScript 中的变量是没有类型的，只有值才有。变量可以随时持有任何类型的值。</p>\\n<p>undefined 和 undeclared. 变量在未持有的时候为 undefined, 此时 typeof 返回 undefined. 大多数开发者倾向于将 undefined 等同于 undeclared(未声明),但在 JavaScript 中它们完全是两回事。已在作用域中声明但还没有赋值的变量,是 undefined 的。相反,还没有在作用域中声明过的变量,是 undeclared 的。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> a;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">// undefined</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// ReferenceError: b is not defined</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typeof</span><span style=\\"color:#24292E\\"> a; </span><span style=\\"color:#6A737D\\">// \\"undefined\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">typeof</span><span style=\\"color:#24292E\\"> b; </span><span style=\\"color:#6A737D\\">// \\"undefined\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><p>虽然 b 是一个 undeclared 变量,但 typeof b 并没有报错。这是因为 typeof 有一个特殊的安全防范机制。防止因为未定义导致程序终止运行。</p>\\n<h2 id=\\"值和引用\\" tabindex=\\"-1\\">值和引用 <a class=\\"header-anchor\\" href=\\"#值和引用\\" aria-label=\\"Permalink to &quot;值和引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在许多编程语言中，赋值和参数传递可以通过值复制(value-copy)或者引用复制(reference-copy)来完成，这取决与我们使用什么语法。但是 JavaScript 对值和引用的赋值 / 传递在语法上没有区别,完全根据值的类型来决定。</p>\\n<p>简单值(即标量基本类型值,scalar primitive)总是通过值复制的方式来赋值/传递,包括 null 、 undefined 、字符串、数字、布尔和 ES6 中的 symbol 。</p>\\n<p>复合值(compound value)——对象(包括数组和封装对象)和函数,则总是通过引用复制的方式来赋值/传递。由于引用指向的是值本身而非变量,所以一个引用无法更改另一个引用的指向。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> a </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> b </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> a;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">//[1,2,3]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// [1,2,3]</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">// 然后</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">5</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">6</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">a; </span><span style=\\"color:#6A737D\\">// [1,2,3]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">b; </span><span style=\\"color:#6A737D\\">// [4,5,6]</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br></div></div><p>b=[4,5,6] 并不影响 a 指向值 [1,2,3] ,除非 b 不是指向数组的引用,而是指向 a 的指针,但在 JavaScript 中不存在这种情况!</p>\\n<p>参考：</p>\\n<p><a href=\\"https://github.com/getify/You-Dont-Know-JS\\" target=\\"_blank\\" rel=\\"noreferrer\\">You Don't Know JS</a></p>\\n"}]},"relativePath":"page/23/index.md","filePath":"page/[page].md"}`),e={name:"page/23/index.md"};function l(p,o,r,t,c,i){return a(),n("div")}const u=s(e,[["render",l]]);export{y as __pageData,u as default};
